CREATE TABLE IF NOT EXISTS _migration_113_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_113_guard;
INSERT INTO _migration_113_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM topics WHERE id LIKE 'topic_was_agric_%') = 10 AND (SELECT COUNT(*) FROM syllabus_topics WHERE specification_id = 'spec_wassce_agric_nacca_2025') = 10 THEN 1 ELSE 0 END;
DROP TABLE _migration_113_guard;
